import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"
os.environ["CC"] = "hipcc"

hip_source = """
#include &lt;hip/hip_runtime.h&gt;
#include &lt;torch/extension.h&gt;

torch::Tensor gemm_fp32(torch::Tensor a, torch::Tensor b, torch::Tensor out) {
  auto m = a.size(0);
  auto k = a.size(1);
  auto n = b.size(1);
  dim3 block(32, 8);
  dim3 grid((n + 31) / 32, (m + 7) / 8);
  auto stream = at::cuda::getCurrentCUDAStream().stream();
  hipStream_t hip_stream;
  hipStreamCreateWithFlags(&hip_stream, hipStreamFlags::hipStreamDefault);
  gemm_naive_kernel&lt;&lt;&lt;grid, block, 0, hip_stream&gt;&gt;&gt;(a.data_ptr&lt;float&gt;(), b.data_ptr&lt;float&gt;(), out.data_ptr&lt;float&gt;(), m, n, k);
  hipStreamSynchronize(hip_stream);
  hipStreamDestroy(hip_stream);
  return out;
}

__global__ void gemm_naive_kernel(const float *A, const float *B, float *C, int M, int N, int K) {
  int m = blockIdx.y * blockDim.y + threadIdx.y;
  int n = blockIdx.x * blockDim.x + threadIdx.x;
  if (m &lt; M &amp;&amp; n &lt; N) {
    float sum = 0.0f;
    for (int k = 0; k &lt; K; k++) {
      sum += A[m * K + k] * B[k * N + n];
    }
    C[m * N + n] = sum;
  }
}
"""

gemm_fp32 = load_inline(
    name="gemm_fp32",
    cpp_sources=hip_source,
    functions=["gemm_fp32"],
    verbose=True,
    functions_thunk_dispatch={"gemm_fp32": "gemm_fp32_hip"},
)

class Model(nn.Module):
    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        if use_e4m3:
            self.fp8_dtype = torch.float8_e4m3fn
            self.fp8_max = 448.0
        else:
            self.fp8_dtype = torch.float8_e5m2
            self.fp8_max = 57344.0

        self.weight = nn.Parameter(torch.randn(K, N) * 0.02)

    def compute_scale(self, x: torch.Tensor) -> torch.Tensor:
        amax = x.abs().max()
        scale = self.fp8_max / amax.clamp(min=1e-12)
        return scale

    def quantize_to_fp8(self, x: torch.Tensor, scale: torch.Tensor) -> torch.Tensor:
        x_scaled = x * scale
        x_clamped = x_scaled.clamp(-self.fp8_max, self.fp8_max)
        return x_clamped.to(self.fp8_dtype)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        input_dtype = x.dtype
        batch_size = x.shape[0]
        seq_len = x.shape[1]
        x_2d = x.view(-1, self.K)

        x_scale = self.compute_scale(x_2d)
        w_scale = self.compute_scale(self.weight)

        x_fp8 = self.quantize_to_fp8(x_2d, x_scale)
        w_fp8 = self.quantize_to_fp8(self.weight, w_scale)

        x_scale_inv = (1.0 / x_scale).to(torch.float32)
        w_scale_inv = (1.0 / w_scale).to(torch.float32)

        x_de = x_fp8.to(torch.float32) * x_scale_inv
        w_de = w_fp8.to(torch.float32) * w_scale_inv

        out_fp32 = torch.empty((x_2d.size(0), self.N), dtype=torch.float32, device=x.device, memory_format=torch.contiguous_format)
        gemm_fp32(x_de, w_de, out_fp32)

        out = out_fp32.to(input_dtype)
        return out.view(batch_size, seq_len, self.N)

