#include <hip/hip_runtime.h>
#include <torch/extension.h>

torch::Tensor gemm_fp32_hip(torch::Tensor a, torch::Tensor b, torch::Tensor out) {
  int m = a.size(0);
  int n = b.size(1);
  int k = a.size(1);
  dim3 threads(32, 8);
  dim3 blocks((n + threads.x - 1) / threads.x, (m + threads.y - 1) / threads.y);
  gemm_naive_kernel<<<blocks, threads>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), m, n, k);
  return out;
}

__global__ void gemm_naive_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
  const int m = blockIdx.y * blockDim.y + threadIdx.y;
  const int n = blockIdx.x * blockDim.x + threadIdx.x;
  if (m >= M || n >= N) return;
  float sum = 0.0f;
  for (int kk = 0; kk < K; ++kk) {
    sum += A[m * K + kk] * B[kk * N + n];
  }
  C[m * N + n] = sum;
}
"""

