import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

constexpr int TILE_M = 64;
constexpr int TILE_N = 64;
constexpr int TILE_K = 64;

__shared__ float As[TILE_M][TILE_K];
__shared__ float Bs_gate[TILE_K][TILE_N];
__shared__ float Bs_up[TILE_K][TILE_N];

__global__ void fused_gated_ffn_kernel(
    const float *A, 
    const float *B_gate, 
    const float *B_up, 
    float *C,
    int M, 
    int N, 
    int K
) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = bx * TILE_M + ty;
    int col = by * TILE_N + tx;
    if (row >= M || col >= N) return;
    float acc_gate = 0.0f;
    float acc_up = 0.0f;
    int num_tiles = (K + TILE_K - 1) / TILE_K;
    for (int t = 0; t < num_tiles; ++t) {
        As[ty][tx] = 0.0f;
        if (tx < TILE_K && t * TILE_K + tx < K) {
            As[ty][tx] = A[row * K + t * TILE_K + tx];
        }
        Bs_gate[ty][tx] = 0.0f;
        if (ty < TILE_K && t * TILE_K + ty < K) {
            Bs_gate[ty][tx] = B_gate[col * K + t * TILE_K + ty];
        }
        Bs_up[ty][tx] = 0.0f;
        if (ty < TILE_K && t * TILE_K + ty < K) {
            Bs_up[ty][tx] = B_up[col * K + t * TILE_K + ty];
        }
        __syncthreads();
        for (int kk = 0; kk < TILE_K; ++kk) {
            acc_gate += As[ty][kk] * Bs_gate[kk][tx];
            acc_up += As[ty][kk] * Bs_up[kk][tx];
        }
        __syncthreads();
    }
    float gate = acc_gate;
    float sig = 1.0f / (1.0f + __expf(-gate));
    C[row * N + col] = gate * sig * acc_up;
}

__shared__ float As_down[TILE_M][TILE_K];
__shared__ float Bs_down[TILE_K][TILE_N];

__global__ void fused_down_kernel(
    const float *A, 
    const float *B_down, 
    float *C,
    int M, 
    int N, 
    int K
) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = bx * TILE_M + ty;
    int col = by * TILE_N + tx;
    if (row >= M || col >= N) return;
    float acc = 0.0f;
    int num_tiles = (K + TILE_K - 1) / TILE_K;
    for (int t = 0; t < num_tiles; ++t) {
        As_down[ty][tx] = 0.0f;
        if (tx < TILE_K && t * TILE_K + tx < K) {
            As_down[ty][tx] = A[row * K + t * TILE_K + tx];
        }
        Bs_down[ty][tx] = 0.0f;
        if (ty < TILE_K && t * TILE_K + ty < K) {
            Bs_down[ty][tx] = B_down[col * K + t * TILE_K + ty];
        }
        __syncthreads();
        for (int kk = 0; kk < TILE_K; ++kk) {
            acc += As_down[ty][kk] * Bs_down[kk][tx];
        }
        __syncthreads();
    }
    C[row * N + col] = acc;
}

torch::Tensor fused_gate_silu_mul_hip(
    torch::Tensor input,
    torch::Tensor gate_w,
    torch::Tensor up_w
) {
    int64_t N_ = input.size(0);
    int64_t K_ = input.size(1);
    int64_t M_ = gate_w.size(0);
    int N = static_cast<int>(N_);
    int K = static_cast<int>(K_);
    int M_out = static_cast<int>(M_);
    input = input.contiguous();
    gate_w = gate_w.contiguous();
    up_w = up_w.contiguous();
    auto out = torch::empty({N_, M_}, input.options());
    dim3 block(TILE_N, TILE_M);
    dim3 grid(
        (N + TILE_M - 1) / TILE_M,
        (M_out + TILE_N - 1) / TILE_N
    );
    size_t shmem_bytes = sizeof(float) * (TILE_M * TILE_K + 2 * TILE_K * TILE_N);
    hipLaunchKernelGGL(
        fused_gated_ffn_kernel,
        grid,
        block,
        shmem_bytes,
        0,
        input.data_ptr<float>(),
        gate_w.data_ptr<float>(),
        up_w.data_ptr<float>(),
        out.data_ptr<float>(),
        N,
        M_out,
        K
    );
    return out;
}

torch::Tensor fused_down_hip(
    torch::Tensor input,
