cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

constexpr int TILE_M = 16;
constexpr int TILE_N = 64;
constexpr int TILE_K = 64;

__global__ void fused_gated_ffn_kernel(
    const float *A, 
    const float *B_gate, 
    const float *B_up, 
    float *C,
    int M, 
    int N, 
    int K
) {
    __shared__ float As[TILE_M][TILE_K];
    __shared__ float Bs_gate[TILE_K][TILE_N];
    __shared__ float Bs_up[TILE_K][TILE_N];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = bx * TILE_M + ty;
    int col = by * TILE_N + tx;
    if (row >= M || col >= N) return;

    float acc_gate = 0.0f;
    float acc_up = 0.0f;

    int num_tiles = (K + TILE_K - 1) / TILE_K;
    for (int t = 0; t < num_tiles; ++t) {
        As[ty][tx] = 0.0f;
        if (tx < TILE_K && row < M && (t * TILE_K + tx) < K) {
            As[ty][tx] = A[row * K + t * TILE_K + tx];
        }
        Bs_gate[ty][tx] = 0.0f;
        if (ty < TILE_K && col < N && (t * TILE_K + ty) < K) {
            Bs_gate[ty][tx] = B_gate[col * K + t * TILE_K + ty];
        }
        Bs_up[ty][tx] = 0.0f;
        if (ty < TILE_K && col < N && (t * TILE_K + ty) < K) {
            Bs_up[ty][tx] = B_up[col * K + t * TILE_K + ty];
        }
        __syncthreads();
        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            acc_gate += As[ty][kk] * Bs_gate[kk][tx];
            acc_up += As[ty][kk] * Bs_up[kk][tx];
        }
        __syncthreads();
    }
    float gate = acc_gate;
    float sig = 1.0f / (1.0f + __expf(-gate));
    C[row * N + col] = gate * sig * acc_up;
}

__global__ void fused_down_kernel(
    const float *A, 
    const float *B_down, 
    float *C,
    int M, 
    int N, 
    int K
) {
    __shared__ float As[TILE_M][TILE_K];
    __shared__ float Bs[TILE_K][TILE_N];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = bx * TILE_M + ty;
    int col = by * TILE_N + tx;
    if (row >= M || col >= N) return;

    float acc = 0.0f;

    int num_tiles = (K + TILE_K - 1) / TILE_K;
    for (int t = 0; t < num_tiles; ++t) {
        As[ty][tx] = 0.0f;
        if (tx < TILE_K && row < M && (t * TILE_K + tx) < K) {
            As[ty][tx] = A[row * K + t * TILE_K + tx];
        }
        Bs[ty][tx] = 0.0f;
        if (ty < TILE_K && col < N && (t * TILE_K + ty) < K) {
            Bs[ty][tx] = B_down[col * K + t * TILE_K + ty];
        }
        __syncthreads();
        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            acc += As[ty][kk] * Bs[kk][tx];
        }
        __syncthreads();
    }
    C[row * N + col] = acc;
}

torch::Tensor fused_gate_silu_mul_hip(
    torch::Tensor input,
    torch::Tensor gate_w,
    torch::Tensor up_w
) {
    TORCH_CHECK(input.dim() == 2, "input must be 2D");
    TORCH_CHECK(gate_w.dim() == 2, "gate_w must be 2D");
    TORCH_CHECK(up_w.dim() == 2, "up_w must be 2D");

    int64_t n_rows = input.size(0);
    int64_t k_dim = input.size(1);
    int64_t n_cols = gate_w.size(0);
    TORCH_CHECK(gate_w.size(1) == k_dim, "gate_w size mismatch");
    TORCH_CHECK(up_w.size(0) == n_cols, "up_w size mismatch");
    TORCH_CHECK(up_w.size(1) == k_dim, "up_w size mismatch");

    int M = static_cast<int>(n_rows);
    int N = static_cast<int>(n_cols);
    int K = static_cast<int>(k_dim);

    input = input.contiguous();
    gate_w = gate_w.contiguous();
    up_w = up_w.contiguous();

    auto out = torch::zeros({n_rows, n_cols}, input.options());

    dim3 block(TILE_N, TILE_M);
    dim3 grid(
        (M + TILE_M - 1) / TILE_M,
        (N + TILE_N - 1) / TILE_N
    );

    size_t shmem_bytes = sizeof(float) * (TILE_M * TILE_K + 2 * TILE_K * TILE_N);

    hipLaunchKernelGGL(
        fused_gated_ffn_kernel,
        grid,
        block,
        shmem_bytes,
        0,
        input.data_ptr<float>(),
        gate_w.data_ptr<float>(),
        up_w.data_ptr<float>(),
        out.data_ptr<float>(),
        M, 
        N, 
        K
    );
    return out;
}

torch::Tensor fused_down_hip(
    torch::Tensor input,
    torch::Tensor down_w
) {
    TORCH_CHECK(input.dim() == 2, "input must be 2D");
    TORCH_CHECK(down_w.dim() == 2, "down_w must be 2D");

    int64_t n_rows = input.size(0);
    int64_t k_dim = input.size(1);
    int64_t n_cols = down_w.size(0);
    TORCH_CHECK(down_w.size(1) == k_dim, "down_w size mismatch");

    int M = static_cast<int>(n_rows);
    int N = static_cast<int>(n_cols);
    int K = static_cast<int>(k_dim);

    input = input.contiguous();
    down_w = down_w.contiguous();

    auto out = torch::zeros({n_rows, n_cols}, input.options());

    dim3 block(TILE_N, TILE_M);
    dim3 grid(
        (M + TILE_M - 1) / TILE_M,
        (N + TILE_N - 1) / TILE_N
    );

    size_t shmem_bytes = sizeof(float) * (TILE_M * TILE_K + TILE_K * TILE_N);

    hipLaunchKernelGGL(
        fused_down_kernel,
        grid,
        block,
        shmem_bytes,
        0,
        input.data_ptr<float>(),
        down_w.data_ptr<float>(),
        out.data_ptr<float>(),
        M,
        N,
        K
    );
    return out;
}
"""

