cpp_source = """
#include <hip/hip_runtime.h>

__global__ void dequant_gemm_kernel(
    const half * __restrict__ A, int lda_row,
    const uint8_t * __restrict__ W_packed, int ldwp_row,
    const half * __restrict__ S, int lds_row,
    half * __restrict__ C, int ldc_row,
    int M, int N, int K, int group_size, int num_groups
) {
    constexpr int TM = 128;
    constexpr int TN = 128;
    constexpr int TK = 64;
    constexpr int RS = 4;
    constexpr int CS = 4;
    constexpr int NT_M = TM / RS;
    constexpr int NT_N = TN / CS;
    constexpr int BLOCK_SIZE = NT_M * NT_N;

    __shared__ half sh_a[TM * TK];
    __shared__ float sh_w[TN * TK];

    const int tx = threadIdx.x;
    const int lane_m = tx % NT_M;
    const int lane_n = tx / NT_M;

    float acc[RS][CS] = {{0.0f}};

    const int m_base = blockIdx.x * TM;
    const int n_base = blockIdx.y * TN;

    for (int k_outer = 0; k_outer < K; k_outer += TK) {
        // Load A tile to sh_a
        for (int i = tx; i < TM * TK; i += BLOCK_SIZE) {
            const int idx = i;
            const int jm = idx / TK;
            const int jk = idx % TK;
            const int gm = m_base + jm;
            const int gk = k_outer + jk;
            if (gm < M && gk < K) {
                sh_a[idx] = A[gm * lda_row + gk];
            } else {
                sh_a[idx] = __float2half(0.0f);
            }
        }

        // Load dequantized W tile to sh_w
        for (int i = tx; i < TN * TK; i += BLOCK_SIZE) {
            const int idx = i;
            const int jn = idx / TK;
            const int jk = idx % TK;
            const int gn = n_base + jn;
            const int gk = k_outer + jk;
            if (gn < N && gk < K) {
                const int byte_idx = gk / 2;
                const uint8_t p = W_packed[gn * ldwp_row + byte_idx];
                const int wq = (gk % 2 == 0) ? (p & 0x0F) : ((p >> 4) & 0x0F);
                const int gg = gk / group_size;
                const half sc = S[gn * lds_row + gg];
                const float dw = __half2float(sc) * (static_cast<float>(wq) - 8.0f);
                sh_w[idx] = dw;
            } else {
                sh_w[idx] = 0.0f;
            }
        }

        __syncthreads();

        // Compute GEMM tile
        for (int tk = 0; tk < TK; ++tk) {
            for (int jj = 0; jj < CS; ++jj) {
                const int ln = lane_n * CS + jj;
                if (ln < TN) {
                    const float wv = sh_w[ln * TK + tk];
                    for (int ii = 0; ii < RS; ++ii) {
                        const int lm = lane_m * RS + ii;
                        if (lm < TM) {
                            const float av = __half2float(sh_a[lm * TK + tk]);
                            acc[ii][jj] += av * wv;
                        }
                    }
                }
            }
        }

        __syncthreads();
    }

    // Store results
    for (int ii = 0; ii < RS; ++ii) {
        const int lm = lane_m * RS + ii;
        const int gm = m_base + lm;
        if (gm < M) {
            for (int jj = 0; jj < CS; ++jj) {
                const int ln = lane_n * CS + jj;
                const int gn = n_base + ln;
                if (gn < N) {
                    C[gm * ldc_row + gn] = __float2half(acc[ii][jj]);
                }
            }
        }
    }
}

torch::Tensor dequant_gemm_forward(torch::Tensor x, torch::Tensor weight_packed, torch::Tensor scales) {
    const int64_t M = x.size(0);
    const int64_t K = x.size(1);
    const int64_t N = weight_packed.size(0);
    const int64_t PK = weight_packed.size(1);
    const int64_t Ng = scales.size(1);
    const int group_size = static_cast<int>(K / Ng);

    auto out = torch::zeros({M, N}, x.options());

    constexpr int TM = 128;
    constexpr int TN = 128;
    constexpr int TK = 64;
    constexpr int RS = 4;
    constexpr int CS = 4;
    constexpr int NT_M = TM / RS;
    constexpr int NT_N = TN / CS;
    constexpr int block_size = NT_M * NT_N;

    dim3 block(block_size);
    dim3 grid((M + TM - 1) / TM, (N + TN - 1) / TN);

    constexpr size_t shmem_bytes = TM * TK * sizeof(half) + TN * TK * sizeof(float);

    const half* a_ptr = static_cast<const half*>(x.data_ptr());
    const uint8_t* wp_ptr = static_cast<const uint8_t*>(weight_packed.data_ptr());
    const half* s_ptr = static_cast<const half*>(scales.data_ptr());
    half* c_ptr = static_cast<half*>(out.data_ptr());

    dequant_gemm_kernel<<<grid, block, shmem_bytes>>>(
        a_ptr, static_cast<int>(x.stride(0)),
        wp_ptr, static_cast<int>(weight_packed.stride(0)),
        s_ptr, static_cast<int>(scales.stride(0)),
        c_ptr, static_cast<int>(out.stride(0)),
        static_cast<int>(M), static_cast<int>(N), static_cast<int>(K), group_size, static_cast<int>(Ng)
    );

    hipDeviceSynchronize();

    return out;
}
"""

