gated_delta_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void gated_delta_kernel(
    const float *q, size_t sbhq, size_t ssqq,
    const float *k, size_t sbhk, size_t ssqk,
    const float *v, size_t sbhv, size_t ssvq,
    const float *alpha, size_t sbha, size_t ssaq,
    const float *beta, size_t sbhb, size_t ssbq,
    float *o, size_t sbho, size_t ssqo,
    int bh_total, int n_seq, int dv_loc, int dqk_loc
) {
    int s = blockIdx.x;
    if (s >= bh_total) return;
    extern __shared__ float shmem[];
    float* S_sh = shmem;
    size_t pitch_s = (size_t)dqk_loc;
    float* v_sh = S_sh + dv_loc * pitch_s;
    float* k_sh = v_sh + dv_loc;
    float* q_sh = k_sh + dqk_loc;
    int tid = threadIdx.x;
    float alph = 0.0f;
    float bet = 0.0f;
    if (tid < dv_loc) {
        int i = tid;
        size_t ioff = (size_t)i * pitch_s;
        for (int jj = 0; jj < dqk_loc; jj++) {
            S_sh[ioff + jj] = 0.0f;
        }
    }
    __syncthreads();
    for (int t = 0; t < n_seq; t++) {
        if (tid == 0) {
            size_t base_a = (size_t)s * sbha + (size_t)t * ssaq;
            alph = alpha[base_a];
            size_t base_b = (size_t)s * sbhb + (size_t)t * ssbq;
            bet = beta[base_b];
        }
        __syncthreads();
        if (tid < dqk_loc) {
            size_t base_k = (size_t)s * sbhk + (size_t)t * ssqk + (size_t)tid;
            k_sh[tid] = k[base_k];
            size_t base_q = (size_t)s * sbhq + (size_t)t * ssqq + (size_t)tid;
            q_sh[tid] = q[base_q];
        }
        if (tid < dv_loc) {
            size_t base_v = (size_t)s * sbhv + (size_t)t * ssvq + (size_t)tid;
            v_sh[tid] = v[base_v];
        }
        __syncthreads();
        if (tid < dv_loc) {
            int i = tid;
            size_t ioff = (size_t)i * pitch_s;
            float sk = 0.0f;
            for (int jj = 0; jj < dqk_loc; jj++) {
                sk += S_sh[ioff + jj] * k_sh[jj];
            }
            float err = sk - v_sh[i];
            for (int jj = 0; jj < dqk_loc; jj++) {
                float sval = S_sh[ioff + jj];
                S_sh[ioff + jj] = alph * sval - bet * err * k_sh[jj];
            }
            float otv = 0.0f;
            for (int jj = 0; jj < dqk_loc; jj++) {
                otv += S_sh[ioff + jj] * q_sh[jj];
            }
            size_t base_o = (size_t)s * sbho + (size_t)t * ssqo + (size_t)i;
            o[base_o] = otv;
        }
        __syncthreads();
    }
}

torch::Tensor gated_delta_hip(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    torch::Tensor alpha,
    torch::Tensor beta
) {
    TORCH_CHECK(q.device().is_hip(), "q must be HIP tensor");
    TORCH_CHECK(k.device().is_hip(), "k must be HIP tensor");
    TORCH_CHECK(v.device().is_hip(), "v must be HIP tensor");
    TORCH_CHECK(alpha.device().is_hip(), "alpha must be HIP tensor");
