    TORCH_CHECK(k.size(0) == bh_ && k.size(1) == seq_ && k.size(2) == dqk_);
    auto o = torch::empty({bh_, seq_, dv_}, q.options());
    if (bh_ == 0) return o;
    dim3 block(256);
    dim3 grid(static_cast<unsigned int>(bh_));
    size_t shmem_sz = ((size_t)dv_ * dqk_ + dv_ + dqk_ + dqk_ + 128) * sizeof(float);
