import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_source = """
#include <hip/hip_runtime.h>

__global__ void dequant_gemm_kernel(
    const half *A, int lda_row,
    const uint8_t *W_packed, int ldwp_row,
    const half *S, int lds_row,
    half *C, int ldc_row,
    int M, int N, int K, int group_size, int num_groups
) {
    constexpr int TM = 64;
    constexpr int TN = 64;
    constexpr int TK = 64;
    constexpr int RS = 4;
    constexpr int CS = 4;
    constexpr int NT_M = TM / RS;
    constexpr int NT_N = TN / CS;
    constexpr int block_size = NT_M * NT_N;

    extern __shared__ char shmem[];
    half* sh_a = reinterpret_cast<half*>(shmem);
    float* sh_w = reinterpret_cast<float*>(shmem + TM * TK * sizeof(half));

    int tx = threadIdx.x;
    int lane_m = tx % NT_M;
    int lane_n = tx / NT_M;

    float acc[RS][CS];
    #pragma unroll
    for (int i = 0; i < RS; i++) {
        #pragma unroll
        for (int j = 0; j < CS; j++) {
            acc[i][j] = 0.0f;
        }
    }

    int m_base = blockIdx.x * TM;
    int n_base = blockIdx.y * TN;

    for (int k_outer = 0; k_outer < K; k_outer += TK) {
        // Load A
        for (int i = tx; i < TM * TK; i += block_size) {
            int idx = i;
            int jm = idx / TK;
            int jk = idx % TK;
            int gm = m_base + jm;
            int gk = k_outer + jk;
            if (gm < M && gk < K) {
                sh_a[idx] = A[gm * lda_row + gk];
            } else {
                sh_a[idx] = __float2half(0.0f);
            }
        }

        // Load W dequant
        for (int i = tx; i < TN * TK; i += block_size) {
            int idx = i;
            int jn = idx / TK;
            int jk = idx % TK;
            int gn = n_base + jn;
            int gk = k_outer + jk;
            if (gn < N && gk < K) {
                int byte_idx = gk / 2;
                uint8_t p = W_packed[gn * ldwp_row + byte_idx];
                int wq = (gk % 2 == 0) ? (p & 0x0F) : ((p >> 4) & 0x0F);
                int gg = gk / group_size;
                half sc = S[gn * lds_row + gg];
                float dw = __half2float(sc) * (static_cast<float>(wq) - 8.0f);
                sh_w[idx] = dw;
            } else {
                sh_w[idx] = 0.0f;
            }
        }

        __syncthreads();

        // Compute
        #pragma unroll
        for (int tk = 0; tk < TK; tk++) {
            #pragma unroll
            for (int jj = 0; jj < CS; jj++) {
                int ln = lane_n * CS + jj;
                if (ln < TN) {
                    float wv = sh_w[ln * TK + tk];
                    #pragma unroll
                    for (int ii = 0; ii < RS; ii++) {
                        int lm = lane_m * RS + ii;
                        if (lm < TM) {
                            float av = __half2float(sh_a[lm * TK + tk]);
                            acc[ii][jj] += av * wv;
                        }
                    }
                }
            }
        }

        __syncthreads();
    }

    // Store
    #pragma unroll
    for (int ii = 0; ii < RS; ii++) {
        int lm = lane_m * RS + ii;
        int gm = m_base + lm;
        if (gm < M) {
            #pragma unroll
            for (int jj = 0; jj < CS; jj++) {
                int ln = lane_n * CS + jj;
                int gn = n_base + ln;
                if (gn < N) {
                    C[gm * ldc_row + gn] = __float2half(acc[ii][jj]);
                }
            }
        }
    }
}

torch::Tensor dequant_gemm_forward(torch::Tensor x, torch::Tensor weight_packed, torch::Tensor scales) {
    int M = x.size(0);
    int K = x.size(1);
    int N = weight_packed.size(0);
    int Ng = scales.size(1);
    int group_size = K / Ng;

    auto out = torch::zeros({M, N}, x.options());

    constexpr int TM = 64;
    constexpr int TN = 64;
    constexpr int TK = 64;
    constexpr int block_size = 256;
    dim3 block(block_size);
    dim3 grid((M + TM - 1) / TM, (N + TN - 1) / TN);

    constexpr size_t shmem_bytes = TM * TK * sizeof(half) + TN * TK * sizeof(float);

    const half* a_ptr = static_cast<const half*>(x.data_ptr());
    const uint8_t* wp_ptr = static_cast<const uint8_t*>(weight_packed.data_ptr());
    const half* s_ptr = static_cast<const half*>(scales.data_ptr());
    half* c_ptr = static_cast<half*>(out.data_ptr());

    dequant_gemm_kernel<<<grid, block, shmem_bytes>>>(
        a_ptr, x.stride(0),
        wp_ptr, weight_packed.stride(0),
        s_ptr, scales.stride(0),
        c_ptr, out.stride(0),
        M, N, K, group_size, Ng
    );

    (void)hipDeviceSynchronize();

    return out;
}
"""

dequant_gemm = load_inline(
    name="dequant_int4_gemm",
    cpp_sources=cpp_source, 
