#include <hip/hip_runtime.h>

__global__ void simple_dequant_gemm(
    const half *A, int lda_row,
    const uint8_t *W_packed, int ldwp_row,
    const half *S, int lds_row,
    half *C, int ldc_row,
    int M, int N, int K, int group_size, int num_groups
) {
    int m = blockIdx.x * blockDim.x + threadIdx.x;
    int n = blockIdx.y * blockDim.y + threadIdx.y;
    if (m < M && n < N) {
        float acc = 0.0f;
        for (int k = 0; k < K; k += 2) {
            int byte_idx = k / 2;
            uint8_t p = W_packed[n * ldwp_row + byte_idx];
            int w0 = p & 0x0F;
            int w1 = (p >> 4) & 0x0F;
            int g = k / group_size;
            half sc = S[n * lds_row + g];
            // Match naive: (w_fp16 - 8_fp16) * sc_fp16
            half w0_h = __float2half(static_cast<float>(w0));
            half centered0 = w0_h - __float2half(8.0f);
            half dw0_h = centered0 * sc;
            float dw0 = __half2float(dw0_h);
            half w1_h = __float2half(static_cast<float>(w1));
            half centered1 = w1_h - __float2half(8.0f);
            half dw1_h = centered1 * sc;
            float dw1 = __half2float(dw1_h);
            float a0 = __half2float(A[m * lda_row + k]);
            float a1 = __half2float(A[m * lda_row + k + 1]);
            acc += a0 * dw0 + a1 * dw1;
        }
        C[m * ldc_row + n] = __float2half(acc);
    }
}

