    const half* a_ptr = static_cast<const half*>(x.data_ptr());
    const uint8_t* wp_ptr = static_cast<const uint8_t*>(weight_packed.data_ptr());
    const half* s_ptr = static_cast<const half*>(scales.data_ptr());
