__global__ void simple_gate_up_kernel(
    const float *A, 
    const float *B_gate, 
    const float *B_up, 
    float *C,
    int M, 
    int N, 
    int K
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * N) {
        int row = idx / N;
        int col = idx % N;
        float gate_s = 0.0f;
        float up_s = 0.0f;
        for (int k = 0; k < K; ++k) {
            float a = A[row * K + k];
            gate_s += a * B_gate[col * K + k];
            up_s += a * B_up[col * K + k];
        }
        float sig = 1.0f / (1.0f + __expf(-gate_s));
        C[row * N + col] = gate_s * sig * up_s;
    }
}

