#include <hip/hip_runtime.h>

__global__ void dequant_gemm_kernel(
    const half *A, int lda_row,
    const uint8_t *W_packed, int ldwp_row,
    const half *S, int lds_row,
    half *C, int ldc_row,
    int M, int N, int K, int group_size, int num_groups
) {
    constexpr int TM = 64;
    constexpr int TN = 64;
    constexpr int TK = 64;
    constexpr int RS = 4;
    constexpr int CS = 4;
    constexpr int NT_M = TM / RS;
    constexpr int NT_N = TN / CS;
    constexpr int block_size = NT_M * NT_N;

    extern __shared__ char shmem[];
    half* sh_a = reinterpret_cast<half*>(shmem);
    half* sh_w = sh_a + TM * TK;

    int tx = threadIdx.x;
    int lane_m = tx % NT_M;
    int lane_n = tx / NT_M;

    float acc[RS][CS];
#pragma unroll
    for (int i = 0; i < RS; ++i) {
#pragma unroll
        for (int j = 0; j < CS; ++j) {
            acc[i][j] = 0.0f;
        }
    }

    int m_base = blockIdx.x * TM;
    int n_base = blockIdx.y * TN;

    for (int k_outer = 0; k_outer < K; k_outer += TK) {
        // Load sh_a
        for (int i = tx; i < TM * TK; i += block_size) {
            int idx = i;
            int jm = idx / TK;
            int jk = idx % TK;
            int gm = m_base + jm;
            int gk = k_outer + jk;
            if (gm < M && gk < K) {
                sh_a[idx] = A[gm * lda_row + gk];
            } else {
                sh_a[idx] = __float2half(0.0f);
            }
        }

        // Load sh_w with FP16 dequant matching naive
        for (int i = tx; i < TN * TK; i += block_size) {
            int idx = i;
            int jn = idx / TK;
            int jk = idx % TK;
            int gn = n_base + jn;
            int gk = k_outer + jk;
            if (gn < N && gk < K) {
                int byte_idx = gk / 2;
                uint8_t p = W_packed[gn * ldwp_row + byte_idx];
                int wq = (gk % 2 == 0) ? (p & 0x0F) : ((p >> 4) & 0x0F);
                int gg = gk / group_size;
                half sc = S[gn * lds_row + gg];
                half w_h = __float2half(static_cast<float>(wq));
                half centered = w_h - __float2half(8.0f);
                half dw_h = centered * sc;
                sh_w[idx] = dw_h;
            } else {
                sh_w[idx] = __float2half(0.0f);
            }
        }

        __syncthreads();

        // Compute
#pragma unroll
        for (int tk = 0; tk < TK; ++tk) {
#pragma unroll
            for (int jj = 0; jj < CS; ++jj) {
                int ln = lane_n * CS + jj;
                if (ln < TN) {
                    float wv = __half2float(sh_w[ln * TK + tk]);
#pragma unroll
                    for (int ii = 0; ii < RS; ++ii) {
                        int lm = lane_m * RS + ii;
                        if (lm < TM) {
                            float av = __half2float(sh_a[lm * TK + tk]);
                            acc[ii][jj] += av * wv;
                        }
                    }
                }
            }
        }
    }

    // Store
#pragma unroll
    for (int ii = 0; ii < RS; ++ii) {
        int lm = lane_m * RS + ii;
        int gm = m_base + lm;
        if (gm < M) {
#pragma unroll
            for (int jj = 0; jj < CS; ++jj) {
                int ln = lane_n * CS + jj;
                int gn = n_base + ln;
                if (gn < N) {
                    C[gm * ldc_row + gn] = __float2half(acc[ii][jj]);
                }
            }
        }
    }
}

